#!/usr/bin/env node
/**
 * Generate extension/host-config.js from host.config.json.
 *
 * `--check` compares instead of writing, and exits 1 on drift. That closes the
 * "hand-edit the generated file, commit it, never run verify" hole: the generated
 * file is tracked so packaging works without a build step, and --check proves the
 * tracked copy still matches its source.
 */
import fs from 'node:fs';

const source = JSON.parse(fs.readFileSync('host.config.json', 'utf8').replace(/^\uFEFF/, ''));
if (!source.hostName || typeof source.hostName !== 'string') {
  console.error('host.config.json must contain a "hostName" string');
  process.exit(2);
}

const target = 'extension/host-config.js';
const body =
  '// Generated by scripts/generate-host-config.mjs from host.config.json. Do not edit.\n' +
  `export const HOST_NAME = ${JSON.stringify(source.hostName)};\n`;

if (process.argv.includes('--check')) {
  if (!fs.existsSync(target)) {
    console.error(`${target} is missing; run npm run setup:extension`);
    process.exit(1);
  }
  // Compare content, not bytes: a Windows checkout with autocrlf rewrites this file to
// CRLF, and a byte comparison then reports drift that does not exist (CI run 43353179298).
const current = fs.readFileSync(target, 'utf8').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
  if (current !== body) {
    console.error(`${target} does not match host.config.json; regenerate it`);
    process.exit(1);
  }
  console.log(`${target}: in sync with host.config.json`);
  process.exit(0);
}

fs.writeFileSync(target, body);
console.log(`${target} -> ${source.hostName}`);
